import { SITE_URL, SITE_NAME, PERSON, abs } from "./site";
import { getPageSeo } from "./pageSeo";

/** Generated by app/opengraph-image.js — 1200×630 PNG. */
const OG_IMAGE_PATH = abs("/opengraph-image");

/**
 * Build Next.js Metadata for a route.
 *
 * @param {string} path  Route path, e.g. "/" or "/resume".
 */
export const commonSeo = (path = "/") => {
  const { title, description } = getPageSeo(path);
  const canonical = abs(path);

  return {
    metadataBase: new URL(SITE_URL),
    title,
    description,
    applicationName: SITE_NAME,
    authors: [{ name: PERSON.name, url: canonical }],
    creator: PERSON.name,
    publisher: PERSON.name,

    alternates: { canonical },

    openGraph: {
      type: "profile",
      title,
      description,
      url: canonical,
      siteName: SITE_NAME,
      locale: "en_US",
      firstName: PERSON.givenName,
      lastName: PERSON.familyName,
      username: "muhammadgohar",
      /* Set explicitly rather than relying on the app/opengraph-image.js file
         convention alone: declaring `openGraph` in a child segment replaces the
         parent's, which silently dropped og:image from every inner page. */
      images: [
        {
          url: OG_IMAGE_PATH,
          width: 1200,
          height: 630,
          alt: `${PERSON.name} — ${PERSON.jobTitle}`,
        },
      ],
    },

    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE_PATH],
    },

    /* Next serialises this into a valid robots directive. The previous
       hand-written string emitted `max-snippet:max`, which is invalid —
       max-snippet only accepts an integer (-1 means "no limit"). */
    robots: {
      index: true,
      follow: true,
      googleBot: {
        index: true,
        follow: true,
        "max-image-preview": "large",
        "max-snippet": -1,
        "max-video-preview": -1,
      },
    },

    category: "technology",

    /* No `keywords`: Google has ignored the meta keywords tag since 2009,
       and the previous 900-character list read as keyword stuffing. */
  };
};
